auto cmp_asc = +[](const void *pa, const void *pb) -> int {
    const char *a = pa ? *(const char *const *)pa : nullptr;
    const char *b = pb ? *(const char *const *)pb : nullptr;
    if (a == b) return 0;
    if (!a) return -1;
    if (!b) return 1;
    return strcmp(a, b);
};
auto cmp_desc = +[](const void *pa, const void *pb) -> int {
