#  - Includes a variety of typical log message content: long/short, spaces, punctuation, unicode, digits
#  - Lengths are constrained (stubs clamp to 64 or 256) so we keep under 512 bytes.
# We return bytes because the harness expects a buffer that its FUZZ_PARAM_STR loader can interpret.

RFC6901_ESCAPES = ["~0", "~1"]

UNICODE_SAMPLES = [
    "αβγ",                # Greek
    "漢字かなカナ",         # CJK + Kana
    "🙂🔥🚀",               # Emoji
    "Здравствуй",         # Cyrillic
    "हिन्दी",             # Devanagari
]

LOG_PREFIXES = [
    "info", "warn", "error", "debug", "trace",
    "user", "system", "net", "json", "auth"
]

JSON_KEYS = [
    "foo", "bar", "baz", "items", "0", "nested", "~", "/", "tilde", "slash",
    "long_key_name_with_numbers_12345", "Unicode", "空", "emoji"
]

def _rand_bool(r: random.Random, p: float) -> bool:
    return r.random() < p

def _pick(r: random.Random, arr: List[str]) -> str:
    return arr[r.randrange(len(arr))]

def _rand_ascii(r: random.Random, min_len: int, max_len: int) -> str:
    n = r.randint(min_len, max_len)
    choices = string.ascii_letters + string.digits + " _-.:,;/@#%+={}[]()"\
              + "\t\n"  # include whitespace to exercise %.*s truncation
    return ''.join(r.choice(choices) for _ in range(n))

def _escape_json_pointer_token(token: str) -> str:
    # RFC6901: ~ -> ~0, / -> ~1
    return token.replace('~', '~0').replace('/', '~1')

def _make_json_pointer(r: random.Random) -> str:
    # Generate a variety of JSON Pointer paths
    kind = r.randrange(8)
    if kind == 0:
        return ""  # empty path (replace root in setf)
    if kind == 1:
        return "/"  # root member name "" (rare but valid if object has empty key)
    # Build 1..5 segments
    segs = []
    seg_count = r.randint(1, 5)
    for _ in range(seg_count):
        choice = r.randrange(6)
        if choice == 0:
            tok = _pick(r, JSON_KEYS)
        elif choice == 1:
            tok = _pick(r, LOG_PREFIXES)
        elif choice == 2:
            tok = str(r.randint(0, 20))  # array indices
        elif choice == 3:
            tok = _rand_ascii(r, 1, 8)
        elif choice == 4:
            tok = _pick(r, UNICODE_SAMPLES)
        else:
            # Include raw special chars that will be escaped
            tok = _rand_ascii(r, 1, 6) + "~/"[r.randrange(2)]
        segs.append(_escape_json_pointer_token(tok))
    return "/" + "/".join(segs)

def _make_log_message(r: random.Random) -> str:
    parts: List[str] = []
    # Optional prefix and numeric code
    if _rand_bool(r, 0.7):
        parts.append(_pick(r, LOG_PREFIXES))
    if _rand_bool(r, 0.5):
        parts.append(str(r.randint(0, 100000)))
    # Random ASCII blob
    parts.append(_rand_ascii(r, 5, 40))
    # Optionally add unicode samples
    if _rand_bool(r, 0.5):
        parts.append(_pick(r, UNICODE_SAMPLES))
    # Optionally include percent signs as data (safe since used with %s)
    if _rand_bool(r, 0.4):
        percents = "%" * r.randint(1, 5)
        parts.append(percents)
    msg = " ".join(parts)
    # Ensure length reasonable for stubs; they cap at 64 or 256 so we keep under 300
    if len(msg) > 300:
        msg = msg[:300]
    return msg

def _compose_seeded_payload(r: random.Random) -> str:
    # Mix JSON Pointer and log message separated to be useful across stubs.
    # The json_pointer_*f stubs will prepend a leading '/' if non-empty; our generator
    # already returns a properly formed path (optionally empty), so that code will leave
    # it as-is or add another leading '/'. Both are fine and still valid for many paths.

    # Choose layout pattern
    pat = r.randrange(5)
    if pat == 0:
        # Just a JSON Pointer path
        return _make_json_pointer(r)
    elif pat == 1:
        # Just a log message
        return _make_log_message(r)
    elif pat == 2:
        # Path then message
        return f"{_make_json_pointer(r)} {_make_log_message(r)}"
    elif pat == 3:
        # Message then path
        return f"{_make_log_message(r)} {_make_json_pointer(r)}"
    else:
        # Interleaved segments with escapes emphasized
        path = _make_json_pointer(r)
        msg = _make_log_message(r)
        extras = []
        if _rand_bool(r, 0.6):
            extras.append(_pick(r, RFC6901_ESCAPES))
        if _rand_bool(r, 0.5):
            extras.append("/" * r.randint(1, 3))
        tail = " ".join(extras)
        combined = f"{msg} | {path} {tail}".strip()
        return combined[:350]

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    s = _compose_seeded_payload(r)
    # Ensure UTF-8 bytes; replace un-encodable characters conservatively (should not happen)
    b = s.encode('utf-8', errors='strict')
    # Respect overall 4096-byte budget; keep well under
    if len(b) > 4096:
        b = b[:4096]
    return b

import random
import struct
import zlib

# Data type: arbitrary bytes
# We generate buffers that are useful for the given fuzz stubs. The stubs primarily
# use FUZZ_PARAM_STR (std::string) as a source for:
# - json_object_new_string_len / json_object_set_string_len: needs arbitrary bytes (possibly including NUL),
#   with lengths up to ~1024. Providing varied content including UTF-8, ASCII, NULs, long runs, etc.,
#   is interesting while remaining valid.
# - json_tokener_parse_ex: uses the provided buffer as JSON input. Provide valid JSON documents of
#   varied shapes and sizes (including with and without a trailing NUL) to hit success paths.
# - printbuf_memappend / fast: arbitrary byte arrays of varying lengths, including empty, small, and larger blocks.
# - json_object_free_userdata: arbitrary bytes copied into malloc() then freed.
#
# Strategy:
# - Mix between several classes of payloads, each valid for the stubs:
#   1) Valid JSON documents (objects/arrays/scalars), of various sizes.
#   2) Random ASCII/UTF-8-like strings.
#   3) Binary blobs with NULs and high bytes.
#   4) Repetitive patterns and edge-case lengths (0, 1, 1024, 2048, etc.).
# - Keep total size <= 4096 bytes.
# - Each call is seeded for reproducibility.

_MAX_TOTAL = 4096

_SIMPLE_ASCII = [
    b"",
    b"a",
    b"0",
    b"true",
    b"false",
    b"null",
    b"{}",
    b"[]",
]

def _rand_ascii(rng: random.Random, n: int) -> bytes:
    alphabet = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 _-:/\\,.{}[]()<>\"'\n\t"
    return bytes(rng.choice(alphabet) for _ in range(n))

def _rand_binary(rng: random.Random, n: int) -> bytes:
    # Include NULs and high bytes
    return bytes(rng.randrange(0, 256) for _ in range(n))

def _repeat_pattern(pattern: bytes, total: int) -> bytes:
    if not pattern:
        return b""
    reps, rem = divmod(total, len(pattern))
    return pattern * reps + pattern[:rem]

def _json_string(rng: random.Random, max_len: int) -> str:
    # Build a JSON string with escaped and unicode content
    parts = []
    length = rng.randint(0, max(0, max_len))
    for _ in range(length):
        t = rng.randrange(0, 6)
        if t == 0:
            parts.append("\\\"")
        elif t == 1:
            parts.append("\\n")
        elif t == 2:
            parts.append("\\t")
        elif t == 3:
            # random BMP unicode escape
            parts.append("\\u%04x" % rng.randrange(0x20, 0x7E))
        else:
            ch = rng.choice("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 _-:/,.")
            parts.append(ch)
    return '"' + ''.join(parts) + '"'

def _json_number(rng: random.Random) -> str:
    # Integers and floats, including exponents
    choice = rng.randrange(0, 5)
    if choice == 0:
        return str(rng.randint(-2**31, 2**31 - 1))
    elif choice == 1:
        return str(rng.randint(0, 2**63 - 1))
    elif choice == 2:
        return ("%.6f" % (rng.random() * (1 if rng.random() < 0.5 else 1e6)))
    elif choice == 3:
        base = rng.uniform(-1e6, 1e6)
        exp = rng.randint(-10, 10)
        return ("%fe%d" % (base, exp))
    else:
        return "0"

def _json_scalar(rng: random.Random) -> str:
    t = rng.randrange(0, 5)
    if t == 0:
        return _json_string(rng, 32)
    if t == 1:
        return _json_number(rng)
    if t == 2:
        return rng.choice(["true", "false"])
    if t == 3:
        return "null"
    return _json_string(rng, 8)

def _json_array(rng: random.Random, depth: int, budget: int) -> str:
    if depth <= 0 or budget <= 2:
        return "[]"
    n = rng.randint(0, max(0, min(6, budget // 4)))
    elems = []
    for _ in range(n):
        elems.append(_json_value(rng, depth - 1, budget // max(1, n)))
    return "[" + ",".join(elems) + "]"

def _json_object(rng: random.Random, depth: int, budget: int) -> str:
    if depth <= 0 or budget <= 2:
        return "{}"
    n = rng.randint(0, max(0, min(6, budget // 6)))
    items = []
    for _ in range(n):
        key = _json_string(rng, 16)
        val = _json_value(rng, depth - 1, budget // max(1, n))
        items.append(f"{key}:{val}")
    return "{" + ",".join(items) + "}"

def _json_value(rng: random.Random, depth: int, budget: int) -> str:
    choice = rng.randrange(0, 6)
    if choice == 0:
        return _json_object(rng, depth - 1, budget)
    if choice == 1:
        return _json_array(rng, depth - 1, budget)
    return _json_scalar(rng)

def _build_valid_json(rng: random.Random, max_bytes: int) -> bytes:
    # Ensure a NUL-terminated option occasionally to help json_tokener_parse_ex finalize numbers
    depth = rng.randint(1, 4)
    budget = max_bytes - 1 if max_bytes > 0 else 0
    txt = _json_value(rng, depth, budget)
    b = txt.encode('utf-8', errors='strict')[:max_bytes]
    # Sometimes append NUL to indicate end-of-input
    if rng.random() < 0.5 and len(b) + 1 <= max_bytes:
        b = b + b"\x00"
    return b

def _build_ascii_blob(rng: random.Random, max_bytes: int) -> bytes:
    # Choose an edge length and fill with ASCII including newlines and quotes
    choices = [0, 1, 2, 7, 15, 63, 127, 255, 512, 1024]
    target = rng.choice(choices + [rng.randint(0, max_bytes)])
    target = min(target, max_bytes)
    if target == 0:
        return rng.choice(_SIMPLE_ASCII)
    return _rand_ascii(rng, target)

def _build_binary_blob(rng: random.Random, max_bytes: int) -> bytes:
    # Mix of random, repeated patterns, and structured headers
    if max_bytes <= 0:
        return b""
    mode = rng.randrange(0, 4)
    if mode == 0:
        # Random binary of random size
        n = rng.randint(0, max_bytes)
        return _rand_binary(rng, n)
    if mode == 1:
        # Repeated small pattern, include NUL bytes
        pattern_len = rng.randint(1, min(16, max_bytes))
        pattern = bytes(rng.randrange(0, 256) for _ in range(pattern_len))
        total = rng.randint(0, max_bytes)
        return _repeat_pattern(pattern, total)
    if mode == 2:
        # Length-prefixed block with checksum suffix
        payload_len = rng.randint(0, max(0, max_bytes - 8))
        payload = _rand_binary(rng, payload_len)
        hdr = struct.pack('<I', payload_len)
        crc = struct.pack('<I', zlib.crc32(payload) & 0xFFFFFFFF)
        blob = hdr + payload + crc
        return blob[:max_bytes]
    # Mixed ascii + binary with embedded NULs
    a_len = rng.randint(0, max_bytes)
    a = _rand_ascii(rng, min(a_len, max_bytes))
    b = _rand_binary(rng, max(0, max_bytes - len(a)))
    # Interleave
    out = bytearray()
    ia = ib = 0
    while len(out) < max_bytes and (ia < len(a) or ib < len(b)):
        if ia < len(a):
            out.append(a[ia]); ia += 1
        if ib < len(b) and len(out) < max_bytes:
            out.append(b[ib]); ib += 1
    return bytes(out)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose one of several content families
    family = rng.randrange(0, 6)
    # Cap for FUZZ_PARAM_STR users: many stubs cap at 1024/512; but json_tokener can use more.
    # Keep under overall 4096.
    if family in (0, 1):
        # Valid JSON document
        max_bytes = rng.randint(2, min(2048, _MAX_TOTAL))
        return _build_valid_json(rng, max_bytes)
    elif family == 2:
        # ASCII blob
        max_bytes = rng.randint(0, min(2048, _MAX_TOTAL))
        return _build_ascii_blob(rng, max_bytes)
    elif family == 3:
        # Binary blob
        max_bytes = rng.randint(0, _MAX_TOTAL)
        return _build_binary_blob(rng, max_bytes)
    elif family == 4:
        # Edge-case lengths filled with zeros or 0xFF
        size = rng.choice([0, 1, 2, 3, 7, 8, 15, 16, 31, 32, 63, 64, 127, 128, 255, 256, 512, 1024, 2048, 3072, 4096])
        size = min(size, _MAX_TOTAL)
        fill = b"\x00" if rng.random() < 0.5 else b"\xFF"
        return fill * size
    else:
        # JSON lines or concatenated JSON values to exercise tokener trailing handling
        parts = []
        count = rng.randint(1, 5)
        remaining = _MAX_TOTAL
        for _ in range(count):
            chunk = _build_valid_json(rng, min(512, remaining))
            parts.append(chunk.rstrip(b"\x00"))  # avoid multiple trailing NULs
            remaining -= len(parts[-1])
            if remaining <= 0:
                break
            if rng.random() < 0.5 and remaining > 0:
                parts.append(b"\n"); remaining -= 1
        out = b"".join(parts)[:_MAX_TOTAL]
        # Occasionally end with NUL to mark end-of-input
        if rng.random() < 0.5 and len(out) + 1 <= _MAX_TOTAL:
            out += b"\x00"
        return out

import random
import json
import string

# Generate valid JSON text bytes to be written to a file by the fuzzer harness.
# The harness picks from a small set (null, [], {}, 0, true). We broaden coverage
# by producing a variety of valid JSON documents that exercise arrays/objects,
# numbers, strings with escapes/Unicode, booleans, and null. All results are
# valid complete JSON texts <= 4096 bytes.

MAX_BYTES = 4096


def _rand_str(rng: random.Random, min_len=0, max_len=32, allow_escapes=True):
    # Produce a JSON-safe string with optional escape sequences and some unicode
    length = rng.randint(min_len, max_len)
    pieces = []
    for _ in range(length):
        choice = rng.random()
        if allow_escapes and choice < 0.08:
            pieces.append(rng.choice(['\\\"', '\\\\', '\\/', '\\b', '\\f', '\\n', '\\r', '\\t']))
        elif allow_escapes and choice < 0.12:
            # \\uXXXX
            cp = rng.randint(0x20, 0x7e)
            pieces.append('\\u%04x' % cp)
        else:
            ch = rng.choice(string.ascii_letters + string.digits + " -_.,:;/?!@#$%^&*()[]{}<>=+|")
            # Avoid raw quotes and backslashes unless escaped
            if ch in ['"', '\\']:
                pieces.append('\\' + ch)
            else:
                pieces.append(ch)
    return ''.join(pieces)


def _rand_number(rng: random.Random):
    # Generate JSON number variants (ints, negatives, fractional, exponent)
    kind = rng.randint(0, 5)
    if kind == 0:
        return str(rng.randint(0, 1_000_000))
    if kind == 1:
        return str(-rng.randint(0, 1_000_000))
    if kind == 2:
        # fractional
        return f"{rng.randint(-1_000_000, 1_000_000)}.{rng.randint(0, 999999):06d}".rstrip('0').rstrip('.')
    if kind == 3:
        # exponent
        mant = rng.randint(-9999, 9999)
        exp = rng.randint(-50, 50)
        return f"{mant}e{exp}"
    if kind == 4:
        # fractional + exponent
        mant_i = rng.randint(-9999, 9999)
        frac = rng.randint(0, 9999)
        exp = rng.randint(-20, 20)
        s = f"{mant_i}.{frac:04d}e{exp}"
        s = s.rstrip('0').rstrip('.')
        return s
    # small special forms
    return rng.choice(["0", "-0", "0.0", "1.0", "3.14159", "2.99792458e8", "-1e-10"])  # valid JSON numbers


def _rand_bool_null(rng: random.Random):
    return rng.choice([True, False, None])


def _rand_leaf(rng: random.Random):
    t = rng.randint(0, 4)
    if t == 0:
        return _rand_bool_null(rng)
    if t == 1:
        return _rand_number(rng)
    if t == 2:
        return _rand_str(rng, 0, 40)
    if t == 3:
        # simple string literals that may trigger parsing paths
        return rng.choice(["", "a", "true", "false", "null", "०१२३", "emoji: 😀"])
    return 0  # small integer


def _build_random_value(rng: random.Random, depth: int = 0):
    # Limit nesting depth to keep size small and avoid excessive recursion
    if depth >= 3:
        # force leaf or small array
        if rng.random() < 0.7:
            return _rand_leaf(rng)
        return [_rand_leaf(rng) for _ in range(rng.randint(0, 4))]

    kind = rng.randint(0, 6)
    if kind == 0:
        return _rand_leaf(rng)
    if kind in (1, 2):
        # array
        n = rng.randint(0, 8)
        return [_build_random_value(rng, depth + 1) for _ in range(n)]
    # object
    n = rng.randint(0, 8)
    obj = {}
    used = set()
    for _ in range(n):
        key = _rand_str(rng, 0, 16)
        # ensure unique keys
        if key in used:
            key += str(rng.randint(0, 999))
        used.add(key)
        obj[key] = _build_random_value(rng, depth + 1)
    return obj


def _to_json_compatible(val):
    # Ensure types are JSON dumpable: numbers delivered as strings are valid JSON numbers
    # We convert numeric strings to a custom wrapper to let json.dumps emit them raw.
    class RawNum(str):
        pass

    if isinstance(val, str):
        return val
    if isinstance(val, bool) or val is None:
        return val
    if isinstance(val, list):
        return [_to_json_compatible(v) for v in val]
    if isinstance(val, dict):
        return {str(k): _to_json_compatible(v) for k, v in val.items()}
    if isinstance(val, (int, float)):
        return val
    # numeric-as-string indicator
    if isinstance(val, RawNum):
        return val
    # If val is a string that contains a number representation we want raw, mark it.
    return val


def _dumps_allow_raw_numbers(obj):
    # json.dumps escapes strings; to allow raw numeric strings, we post-process by
    # replacing quoted numeric strings with raw numbers when they were intended.
    # To keep inputs valid, we only generate numeric strings in leaves not used as keys.
    def mark(o):
        # convert certain strings that are valid JSON number lexemes into Raw holder
        class RawNum(str):
            pass
        def is_num_lex(s: str) -> bool:
            # simple test for a JSON number lexeme
            try:
                # disallow leading +, allow -; ensure it parses as float or int
                if not s:
                    return False
                if s[0] == '+':
                    return False
                # JSON numbers cannot have leading zeros unless zero or 0.xxx
                # We accept a broad set generated by _rand_number
                float(s)
                return True
            except Exception:
                return False
        if isinstance(o, str) and is_num_lex(o):
            return RawNum(o)
        if isinstance(o, list):
            return [mark(v) for v in o]
        if isinstance(o, dict):
            return {k: mark(v) for k, v in o.items()}
        return o

    marked = mark(obj)
    s = json.dumps(marked, ensure_ascii=False, separators=(",", ":"))

    # Replace "<num>" with <num> only where the string is entirely a number and not a key
    # This is safe by doing a simple pass: we avoid touching object keys because they appear before a colon
    out = []
    i = 0
    while i < len(s):
        ch = s[i]
        if ch == '"':
            # try to parse a quoted token
            j = i + 1
            buf = []
            esc = False
            valid = True
            while j < len(s):
                c = s[j]
                if esc:
                    buf.append(c)
                    esc = False
                else:
                    if c == '\\':
                        esc = True
                    elif c == '"':
                        break
                    else:
                        buf.append(c)
                j += 1
            token = ''.join(buf)
            end_quote = j
            # peek next non-space to see if this is a key (followed by colon)
            k = end_quote + 1
            while k < len(s) and s[k].isspace():
                k += 1
            is_key = (k < len(s) and s[k] == ':')
            # emit as raw number if not a key and token is a number lexeme
            def is_num_lex_str(t: str) -> bool:
                if not t or t[0] == '+':
                    return False
                try:
                    float(t)
                    return True
                except Exception:
                    return False
            if (not is_key) and is_num_lex_str(token):
                out.append(token)
            else:
                out.append(s[i:end_quote + 1])
            i = end_quote + 1
        else:
            out.append(ch)
            i += 1
    joined = ''.join(out)
    # Ensure size limit
    if len(joined.encode('utf-8')) > MAX_BYTES:
        # fallback to a minimal JSON
        return "{}"
    return joined


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose a high-level form to encourage diverse code paths in the library
    form = rng.randint(0, 9)

    if form == 0:
        doc = None
    elif form == 1:
        doc = True
    elif form == 2:
        doc = []
    elif form == 3:
        doc = {}
    elif form == 4:
        # simple scalar numbers and strings
        doc = rng.choice([
            0, 1, -1, 123456, -98765, 0.0, 3.1415926535, "hello", "", "true", "false", "null"
        ])
    else:
        # build a structured object or array
        if rng.random() < 0.5:
            doc = _build_random_value(rng, depth=0)
        else:
            # Top-level array mixing types
            arr_len = rng.randint(0, 10)
            doc = [_build_random_value(rng, depth=0) for _ in range(arr_len)]

    # Serialize with compact separators to reduce size; ensure_ascii=False to allow UTF-8
    json_text = _dumps_allow_raw_numbers(doc)

    data = json_text.encode('utf-8')
    if len(data) > MAX_BYTES:
        # fallback small valid JSON per harness expectations
        data = rng.choice([b"null", b"[]", b"{}", b"0", b"true"])
    # Ensure non-empty and valid
    if not data:
        data = b"null"
    return data
